import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile, copyFile } from "node:fs/promises";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { format } from "prettier";

// Use the image processor installed with Next.js; generated files ship with source
// so neither the build nor the first visitor needs to encode the hero.
const root = fileURLToPath(new URL("../", import.meta.url));
const require = createRequire(
  path.join(root, "node_modules/next/package.json"),
);
const sharp = require("sharp");
const widths = [640, 750, 960, 1080, 1280, 1600, 1920, 2560, 3002];
const manifest = { hero: {}, fontPreloads: [] };
const hash = (buffer) =>
  createHash("sha256").update(buffer).digest("hex").slice(0, 12);

await mkdir(path.join(root, "public/images/hero"), { recursive: true });
await mkdir(path.join(root, "public/fonts"), { recursive: true });

for (const [name, original] of [
  ["mobile", "hero-portrait.jpg"],
  ["desktop", "hero-landscape.jpg"],
]) {
  const source = path.join(root, "public/images", original);
  const metadata = await sharp(source).metadata();
  const variants = [];
  for (const width of widths) {
    const buffer = await sharp(source)
      .rotate()
      .resize({ width, withoutEnlargement: true })
      .webp({ quality: 85 })
      .toBuffer();
    const url = `/images/hero/${name}-${width}.${hash(buffer)}.webp`;
    await writeFile(path.join(root, "public", url), buffer);
    variants.push({ width, url });
  }
  manifest.hero[name] = {
    width: metadata.width,
    height: metadata.height,
    src: variants.find((image) => image.width === 750).url,
    srcSet: variants.map((image) => `${image.url} ${image.width}w`).join(", "),
  };
}

const fontPackages = [
  ["@fontsource-variable/manrope", "index.css"],
  ["@fontsource/cormorant-garamond", "400.css"],
  ["@fontsource/cormorant-garamond", "400-italic.css"],
];
const faces = [];
for (const [packageName, cssFile] of fontPackages) {
  const folder = path.join(root, "node_modules", packageName);
  const css = await readFile(path.join(folder, cssFile), "utf8");
  for (const block of css.matchAll(
    /\/\* ([^*]+) \*\/\s*(@font-face\s*\{[^}]+\})/g,
  )) {
    const [, name, face] = block;
    if (!/-latin(?:-ext)?-/.test(name)) continue;
    const font = face.match(/url\(\.\/files\/([^)]*\.woff2)\)/)[1];
    const buffer = await readFile(path.join(folder, "files", font));
    const url = `/fonts/${font.replace(".woff2", `.${hash(buffer)}.woff2`)}`;
    await writeFile(path.join(root, "public", url), buffer);
    faces.push(
      face.replace(/src: [^;]+;/, `src: url("${url}") format("woff2");`),
    );
    if (!name.includes("latin-ext")) manifest.fontPreloads.push(url);
  }
  const licenseName = packageName.endsWith("manrope")
    ? "Manrope-OFL.txt"
    : "Cormorant-Garamond-OFL.txt";
  await copyFile(
    path.join(folder, "LICENSE"),
    path.join(root, "public/fonts", licenseName),
  );
}

await writeFile(
  path.join(root, "src/app/fonts.css"),
  await format(
    `/* Generated by npm run assets:prepare. Original Fontsource files and OFL licenses are preserved. */\n${faces.join("\n\n")}\n`,
    { parser: "css" },
  ),
);
await writeFile(
  path.join(root, "src/lib/visual-assets.json"),
  `${JSON.stringify(manifest, null, 2)}\n`,
);
console.log(
  `Prepared ${widths.length * 2} hero images and ${faces.length} font subsets.`,
);
